    static void install(Path dir,String name,byte[] bytes,Set<String> methods)throws Exception{
        Path path=dir.resolve(name.replace('.','/')+".class");ClassNode target=new ClassNode(),source=new ClassNode();new ClassReader(Files.readAllBytes(path)).accept(target,0);new ClassReader(bytes).accept(source,0);
        for(MethodNode m:source.methods)if(methods.contains(m.name)||m.name.startsWith("lambda$floorPower$")||m.name.contains("backport$roundedDamage")||m.name.contains("backport$stab")||m.name.contains("backport$recordDamage")){target.methods.removeIf(old->old.name.equals(m.name)&&old.desc.equals(m.desc));target.methods.add(m);}
        ClassWriter w=new ClassWriter(0);target.accept(w);Files.write(path,w.toByteArray());
    }
